import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as w,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"前向与后向冲突","description":"","frontmatter":{"title":"前向与后向冲突","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rw-wr-ww.md","filePath":"cs/rw-wr-ww.md","lastUpdated":1789023840000}'),p={name:"cs/rw-wr-ww.md"};function E(h,a,_,B,m,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="前向与后向冲突" tabindex="-1">前向与后向冲突 <a class="header-anchor" href="#前向与后向冲突" aria-label="Permalink to &quot;前向与后向冲突&quot;">​</a></h1><div class="epigraph"><p>读写、写读、写写是三种冲突；图上的边方向记录「谁先」，环意味着无法对应任何串行序。</p><footer>—— 据 Eswaran et al., 1976；Bernstein, Hadzilacos and Goodman 对冲突的整理</footer></div><p><a href="/cs/conflict-serializable">上一课</a>用冲突图无环定义合法交错。本课不重讲「交换非冲突操作」。缺口是边的种类：rw（读后写）、wr（写后读）、ww（写后写）在隔离异常里名字不同——脏读、不可重复读、丢失更新。后课 2PL 要锁的正是这些边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>冲突可串行留下「冲突」。若不分类，锁协议不知道该用共享还是互斥。同一数据项上：wr 边表示后者读到前者的写；rw 表示后者的写使前者的读不能换到后面；ww 是覆盖。缺口是<strong>把图的边写成三种依赖</strong>，对应后课异常名。</p><p><span class="marginnote">前向/后向常相对某一串行序而言：边指向「应该更晚」的事务。本课用 rw/wr/ww 记号，避免和编译课数据依赖术语缠在一起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从调度抽出三元组（事务，对象，读或写），按时间相邻且不可交换则加边。只读事务之间无边。谓词读（范围）的冲突对象是集合，幻象下一单元再展开。本课对象先当点项。</p>',8)),(e(),n(c,null,{default:t(()=>[w(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22%E5%86%99%E5%90%8E%E8%AF%BB%20wr%22%5D%20--%3E%20DIRTY%5B%22%E8%84%8F%E8%AF%BB%E8%8B%A5%E5%86%99%E6%9C%AA%E6%8F%90%E4%BA%A4%22%5D%0A%20%20RW%5B%22%E8%AF%BB%E5%90%8E%E5%86%99%20rw%22%5D%20--%3E%20UNREP%5B%22%E4%B8%8D%E5%8F%AF%E9%87%8D%E5%A4%8D%E8%AF%BB%22%5D%0A%20%20WW%5B%22%E5%86%99%E5%90%8E%E5%86%99%20ww%22%5D%20--%3E%20LOST%5B%22%E4%B8%A2%E5%A4%B1%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三种边给锁管理器分工：读加共享挡住 ww/rw 里写者，写加互斥挡住一切。图有环则不存在相容串行序，必须在运行时避免产生环，而不是事后画图。恢复：wr 若来自未提交写，回滚会级联——严格 2PL 后课切掉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把快照隔离的写集冲突提前。运行时如何只产生无环调度，下一课两阶段锁。</p><p>后课默认：隔离要管 rw、wr、ww。协议是 2PL。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冲突分 wr、rw、ww，对应不同异常。</li><li>环 = 非冲突可串行。</li><li>两阶段锁下一课。</li><li>出处：Eswaran 1976；Bernstein 等。</li></ul>',7))])}const T=i(p,[["render",E]]);export{f as __pageData,T as default};
